// MNIST inference CLI: ./cli_tool weights.json image.png -> prints predicted digit
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>
#include <cmath>
#include "lodepng.h"
extern "C" {
#include "cJSON.h"
}

static bool readFile(const char* path, std::string& out) {
    FILE* f = fopen(path, "rb");
    if (!f) return false;
    fseek(f, 0, SEEK_END);
    long n = ftell(f);
    fseek(f, 0, SEEK_SET);
    out.resize((size_t)n);
    size_t got = n > 0 ? fread(&out[0], 1, (size_t)n, f) : 0;
    fclose(f);
    return got == (size_t)n;
}

// Reads a JSON array of numbers (flat or nested) into a flat vector.
static void flatten(const cJSON* node, std::vector<double>& out) {
    if (!node) return;
    if (cJSON_IsNumber(node)) { out.push_back(node->valuedouble); return; }
    if (cJSON_IsArray(node)) {
        const cJSON* it = NULL;
        cJSON_ArrayForEach(it, node) flatten(it, out);
    }
}

static const cJSON* findKey(const cJSON* root, const char* const* names, int n) {
    for (int i = 0; i < n; i++) {
        const cJSON* v = cJSON_GetObjectItemCaseSensitive((cJSON*)root, names[i]);
        if (v) return v;
    }
    return NULL;
}

static bool getFlat(const cJSON* root, const char* const* names, int n, std::vector<double>& out) {
    const cJSON* v = findKey(root, names, n);
    if (!v) return false;
    out.clear();
    flatten(v, out);
    return !out.empty();
}

int main(int argc, char** argv) {
    if (argc < 3) {
        fprintf(stderr, "usage: %s weights.json image.png\n", argv[0]);
        return 1;
    }

    std::string js;
    if (!readFile(argv[1], js)) { fprintf(stderr, "cannot read %s\n", argv[1]); return 1; }
    cJSON* root = cJSON_Parse(js.c_str());
    if (!root) { fprintf(stderr, "bad json\n"); return 1; }

    static const char* kW1[] = {"input_layer.weight", "input_layer_weight", "w1"};
    static const char* kB1[] = {"input_layer.bias", "input_layer_bias", "b1"};
    static const char* kW2[] = {"hidden_layer.weight", "hidden_layer_weight", "w2"};
    static const char* kB2[] = {"hidden_layer.bias", "hidden_layer_bias", "b2"};
    static const char* kW3[] = {"output_layer.weight", "output_layer_weight", "w3"};
    static const char* kB3[] = {"output_layer.bias", "output_layer_bias", "b3"};

    std::vector<double> W1, B1, W2, B2, W3, B3;
    if (!getFlat(root, kW1, 3, W1) || !getFlat(root, kB1, 3, B1) ||
        !getFlat(root, kW2, 3, W2) || !getFlat(root, kB2, 3, B2) ||
        !getFlat(root, kW3, 3, W3) || !getFlat(root, kB3, 3, B3)) {
        fprintf(stderr, "missing weights\n");
        cJSON_Delete(root);
        return 1;
    }

    double mean = 0.1307, stdv = 0.3081;
    const cJSON* nrm = cJSON_GetObjectItemCaseSensitive(root, "normalization");
    if (nrm) {
        const cJSON* m = cJSON_GetObjectItemCaseSensitive((cJSON*)nrm, "mean");
        const cJSON* s = cJSON_GetObjectItemCaseSensitive((cJSON*)nrm, "std");
        if (cJSON_IsNumber(m)) mean = m->valuedouble;
        if (cJSON_IsNumber(s) && s->valuedouble != 0.0) stdv = s->valuedouble;
    }
    cJSON_Delete(root);

    size_t H1 = B1.size(), H2 = B2.size(), OUT = B3.size();
    size_t IN = H1 ? W1.size() / H1 : 0;
    if (!IN || W1.size() != IN * H1 || W2.size() != H1 * H2 || W3.size() != H2 * OUT) {
        fprintf(stderr, "shape mismatch\n");
        return 1;
    }

    std::vector<unsigned char> img;
    unsigned w = 0, h = 0;
    unsigned err = lodepng::decode(img, w, h, argv[2], LCT_GREY, 8);
    if (err) { fprintf(stderr, "png error %u\n", err); return 1; }
    if ((size_t)w * h != IN) { fprintf(stderr, "image size mismatch\n"); return 1; }

    std::vector<double> x(IN);
    for (size_t i = 0; i < IN; i++) x[i] = (img[i] / 255.0 - mean) / stdv;

    std::vector<double> a(H1), b(H2), o(OUT);
    for (size_t j = 0; j < H1; j++) {
        double s = B1[j];
        const double* row = &W1[j * IN];
        for (size_t i = 0; i < IN; i++) s += row[i] * x[i];
        a[j] = s > 0 ? s : 0;
    }
    for (size_t j = 0; j < H2; j++) {
        double s = B2[j];
        const double* row = &W2[j * H1];
        for (size_t i = 0; i < H1; i++) s += row[i] * a[i];
        b[j] = s > 0 ? s : 0;
    }
    int best = 0;
    for (size_t j = 0; j < OUT; j++) {
        double s = B3[j];
        const double* row = &W3[j * H2];
        for (size_t i = 0; i < H2; i++) s += row[i] * b[i];
        o[j] = s;
        if (s > o[best]) best = (int)j;
    }

    printf("%d\n", best);
    return 0;
}

